import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, getJob, rowToJob } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}
function error(res: ServerResponse, status: number, code: string, message: string, fields?: { field: string; message: string }[]): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}
async function readBody(req: IncomingMessage): Promise<string> {
  let body = '';
  for await (const chunk of req) {
    body += chunk.toString();
    if (body.length > 100_000) throw new Error('body too large');
  }
  return body;
}
function invalid(res: ServerResponse, fields: { field: string; message: string }[]): void {
  error(res, 400, 'invalid_request', 'The request is invalid.', fields);
}

const server = createServer(async (req, res) => {
  const pathname = new URL(req.url ?? '/', 'http://localhost').pathname;
  if (pathname === '/' || pathname === '/health' || pathname === '/api/jobs' || /^\/api\/jobs\/[^/]+$/.test(pathname)) {
    const method = pathname === '/' ? 'GET' : pathname === '/health' || pathname.startsWith('/api/jobs') ? (pathname === '/api/jobs' && req.method === 'POST' ? 'POST' : 'GET') : 'GET';
    if (req.method !== method) return error(res, 405, 'method_not_allowed', 'Method not allowed.');
  } else return error(res, 404, 'not_found', 'Not found.');

  if (pathname === '/' && req.method === 'GET') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' }); res.end(uiHtml); return;
  }
  if (pathname === '/health') {
    const row = db.prepare('SELECT at FROM worker_heartbeat WHERE id=1').get() as { at: number } | undefined;
    return send(res, 200, { status: 'ok', worker: row && Date.now() - Number(row.at) < 3000 ? 'up' : 'down' });
  }
  if (pathname === '/api/jobs' && req.method === 'GET') {
    const rows = db.prepare('SELECT * FROM jobs ORDER BY created_at DESC, rowid DESC').all() as Record<string, unknown>[];
    return send(res, 200, { jobs: rows.map(rowToJob) });
  }
  if (pathname === '/api/jobs' && req.method === 'POST') {
    const fields: { field: string; message: string }[] = [];
    const contentType = req.headers['content-type'] ?? '';
    if (!/^application\/json(?:\s*;|\s*$)/i.test(contentType)) {
      fields.push({ field: 'Content-Type', message: 'Must be application/json.' });
      // Consume the request before returning so the connection can be reused.
      try { await readBody(req); } catch { /* handled as an invalid request */ }
      return invalid(res, fields);
    }
    let parsed: unknown;
    try { parsed = JSON.parse(await readBody(req)); }
    catch { return invalid(res, [{ field: 'body', message: 'Must contain valid JSON.' }]); }
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return invalid(res, [{ field: 'body', message: 'Must be a JSON object.' }]);
    const body = parsed as Record<string, unknown>;
    for (const key of Object.keys(body)) if (!['input', 'steps', 'failAttempts'].includes(key)) fields.push({ field: key, message: 'Unknown field.' });
    if (typeof body.input !== 'string') fields.push({ field: 'input', message: 'Must be a string.' });
    else {
      if (body.input.length < 1 || body.input.length > 1000) fields.push({ field: 'input', message: 'Must be 1 to 1000 characters.' });
      if (!body.input.trim()) fields.push({ field: 'input', message: 'Must not be only whitespace.' });
    }
    const steps = body.steps === undefined ? 5 : body.steps;
    const failAttempts = body.failAttempts === undefined ? 0 : body.failAttempts;
    if (typeof steps !== 'number' || !Number.isInteger(steps) || steps < 1 || steps > 20) fields.push({ field: 'steps', message: 'Must be an integer from 1 to 20.' });
    if (typeof failAttempts !== 'number' || !Number.isInteger(failAttempts) || failAttempts < 0 || failAttempts > 5) fields.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5.' });
    const key = req.headers['idempotency-key'];
    if (key !== undefined && (Array.isArray(key) || !/^[A-Za-z0-9_-]{1,128}$/.test(key))) fields.push({ field: 'Idempotency-Key', message: 'Must contain 1 to 128 letters, numbers, underscores, or hyphens.' });
    if (fields.length) return invalid(res, fields);

    const idempotencyKey = typeof key === 'string' ? key : undefined;
    const normalized = { input: body.input as string, steps: steps as number, failAttempts: failAttempts as number };
    const payload = JSON.stringify(normalized);
    db.exec('BEGIN IMMEDIATE');
    try {
      if (idempotencyKey !== undefined) {
        const prior = db.prepare('SELECT payload, job_id FROM idempotency WHERE key=?').get(idempotencyKey) as { payload: string; job_id: string } | undefined;
        if (prior) {
          db.exec('COMMIT');
          if (prior.payload !== payload) return error(res, 409, 'idempotency_conflict', 'This idempotency key was used with a different payload.');
          return send(res, 200, getJob(db, prior.job_id));
        }
      }
      const id = randomUUID(); const now = new Date().toISOString();
      db.prepare(`INSERT INTO jobs (id,status,input,steps,fail_attempts,attempts,progress_completed,created_at,updated_at)
        VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?)`).run(id, normalized.input, normalized.steps, normalized.failAttempts, now, now);
      if (idempotencyKey !== undefined) db.prepare('INSERT INTO idempotency (key,payload,job_id) VALUES (?,?,?)').run(idempotencyKey, payload, id);
      db.exec('COMMIT');
      return send(res, 201, getJob(db, id));
    } catch (e) { db.exec('ROLLBACK'); throw e; }
  }
  const match = pathname.match(/^\/api\/jobs\/([^/]+)$/);
  if (match) {
    const job = getJob(db, decodeURIComponent(match[1]));
    if (!job) return error(res, 404, 'not_found', 'Job not found.');
    return send(res, 200, job);
  }
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));

