import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });

// A running row belongs to a process that did not finish its work. Requeue it so a
// replacement worker can make progress after either a graceful or abrupt restart.
db.prepare("UPDATE jobs SET status='queued', updated_at=? WHERE status='running'").run(new Date().toISOString());
const heartbeat = () => db.prepare(`INSERT INTO worker_heartbeat (id,at) VALUES (1,?)
  ON CONFLICT(id) DO UPDATE SET at=excluded.at`).run(Date.now());
heartbeat();
const heartbeatTimer = setInterval(heartbeat, 750);

interface Work { id: string; input: string; steps: number; fail_attempts: number; attempts: number }
function claim(): Work | undefined {
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = db.prepare("SELECT id,input,steps,fail_attempts,attempts FROM jobs WHERE status='queued' AND retry_at<=? ORDER BY created_at ASC,rowid ASC LIMIT 1").get(Date.now()) as Work | undefined;
    if (row) db.prepare("UPDATE jobs SET status='running',attempts=attempts+1,progress_completed=0,error=NULL,result_output=NULL,updated_at=? WHERE id=? AND status='queued'").run(new Date().toISOString(), row.id);
    db.exec('COMMIT');
    if (row) row.attempts += 1;
    return row;
  } catch (e) { db.exec('ROLLBACK'); throw e; }
}

async function runJob(job: Work): Promise<void> {
  if (job.attempts <= job.fail_attempts) {
    // The simulated dependency fails before the first step, so progress remains 0.
    if (job.attempts >= 3) {
      db.prepare("UPDATE jobs SET status='failed',error='transient failure',result_output=NULL,updated_at=? WHERE id=? AND status='running'").run(new Date().toISOString(), job.id);
    } else {
      const delay = 500 + Math.floor(Math.random() * 250);
      db.prepare("UPDATE jobs SET status='queued',retry_at=?,updated_at=? WHERE id=? AND status='running'").run(Date.now() + delay, new Date().toISOString(), job.id);
    }
    return;
  }
  for (let n = 1; n <= job.steps; n++) {
    await sleep(100);
    if (stopping) return; // leave running for restart recovery
    db.prepare("UPDATE jobs SET progress_completed=?,updated_at=? WHERE id=? AND status='running'").run(n, new Date().toISOString(), job.id);
  }
  db.prepare("UPDATE jobs SET status='completed',result_output=?,error=NULL,updated_at=? WHERE id=? AND status='running'").run(job.input.toUpperCase(), new Date().toISOString(), job.id);
}

console.log('worker started');
try {
  while (!stopping) {
    const job = claim();
    if (job) await runJob(job);
    else await sleep(100);
  }
} finally {
  clearInterval(heartbeatTimer);
  db.prepare('DELETE FROM worker_heartbeat WHERE id=1').run();
  db.close();
}

