8	    body { font: 16px system-ui, sans-serif; max-width: 850px; margin: 2rem auto; padding: 0 1rem; color: #20242a; }
9	    form { display: grid; gap: .8rem; max-width: 32rem; padding: 1rem; border: 1px solid #ccd2d9; border-radius: 8px; }
10	    label { display: grid; gap: .3rem; } input, button { font: inherit; padding: .5rem; }
11	    button { cursor: pointer; } #form-error { color: #a21b1b; min-height: 1.3em; }
12	    #job-list { list-style: none; padding: 0; } .job { border: 1px solid #ccd2d9; border-radius: 8px; padding: .8rem 1rem; margin: .6rem 0; }
13	    .meta { color: #58616c; font-size: .9rem; }
14	  </style>
15	</head>
16	<body>
17	  <h1>Job tracker</h1>
18	  <form data-testid="job-form">
19	    <label>Input <input data-testid="job-input" name="input" required maxlength="1000"></label>
20	    <label>Steps <input data-testid="job-steps" name="steps" type="number" min="1" max="20" value="5"></label>
21	    <label>Fail attempts <input data-testid="job-fail-attempts" name="failAttempts" type="number" min="0" max="5" value="0"></label>
22	    <button data-testid="job-submit" type="submit">Submit job</button>
23	    <div data-testid="form-error" role="alert"></div>
24	  </form>
25	  <h2>Jobs</h2>
26	  <ul data-testid="job-list"></ul>
27	  <script>
28	    const form = document.querySelector('[data-testid="job-form"]');
29	    const alertRegion = document.querySelector('[data-testid="form-error"]');
30	    const list = document.querySelector('[data-testid="job-list"]');
31	    const input = document.querySelector('[data-testid="job-input"]');
32	    const steps = document.querySelector('[data-testid="job-steps"]');
33	    const fails = document.querySelector('[data-testid="job-fail-attempts"]');
34	    function rejectionText(data) {
35	      const err = data && data.error;
36	      if (!err) return 'The request could not be submitted.';
37	      const fields = err.fields || [];
38	      return fields.length ? `${err.message} ${fields.map(f => `${f.field}: ${f.message}`).join(' ')}` : err.message;
39	    }
40	    async function refresh() {
41	      try {
42	        const response = await fetch('/api/jobs');
43	        const data = await response.json();
44	        if (!response.ok) return;
45	        list.replaceChildren(...data.jobs.map(job => {
46	          const li = document.createElement('li'); li.className = 'job'; li.dataset.testid = 'job-item'; li.dataset.jobId = job.id;
47	          const title = document.createElement('strong'); title.textContent = job.input;
48	          const status = document.createElement('span'); status.dataset.testid = 'job-status'; status.textContent = job.status;
49	          const progress = document.createElement('span'); progress.dataset.testid = 'job-progress'; progress.textContent = `${job.progress.completed}/${job.progress.total}`;
50	          const result = document.createElement('div'); result.dataset.testid = 'job-result'; result.textContent = job.result ? job.result.output : (job.error || '');
51	          const meta = document.createElement('div'); meta.className = 'meta'; meta.append('Status: ', status, ' · Progress: ', progress);
52	          li.append(title, meta, result); return li;
53	        }));
54	      } catch { /* Retry on the next polling interval if the server is restarting. */ }
55	    }
56	    form.addEventListener('submit', async event => {
57	      event.preventDefault(); alertRegion.textContent = '';
58	      try {
59	        const response = await fetch('/api/jobs', { method: 'POST', headers: { 'Content-Type': 'application/json' },
60	          body: JSON.stringify({ input: input.value, steps: Number(steps.value), failAttempts: Number(fails.value) }) });
61	        const data = await response.json();
62	        if (!response.ok) alertRegion.textContent = rejectionText(data);
63	        else { input.value = ''; await refresh(); }
64	      } catch { alertRegion.textContent = 'Unable to submit the job. Please try again.'; }
65	    });
66	    refresh(); setInterval(refresh, 1000);
67	  </script>
68	</body>
69	</html>
